    const endsAt = requireDate(payload, "endsAt");

    if (Date.parse(endsAt) <= Date.parse(startsAt)) {
      throw new ValidationError("endsAt doit etre posterieur a startsAt");
    }

    const room = findRoom(roomId);
    if (!room) {
      throw new ValidationError(`salle inconnue : ${roomId}`);
    }
    if (people > room.capacity) {
      throw new ValidationError(`capacite depassee : ${people} > ${room.capacity}`);
    }

    const clash = bookingsForRoom(roomId).find((b) =>
      overlaps(startsAt, endsAt, b.startsAt, b.endsAt)
    );
    if (clash) {
      res.status(409).json({ error: "creneau deja reserve", conflictsWith: clash.id });
      return;
    }

    const booking = {
      id: nextBookingId(),
      roomId,
      who,
      people,
      startsAt,
      endsAt,
      price: priceFor(room, startsAt, endsAt)
    };
    bookings.push(booking);
    res.status(201).json({ booking });
  } catch (err) {
    if (err instanceof ValidationError) {
      res.status(err.status).json({ error: err.message });
      return;
    }
    throw err;
  }
});

bookingsRouter.delete("/:id", (req, res) => {
  const index = bookings.findIndex((b) => b.id === req.params.id);
  if (index === -1) {
    res.status(404).json({ error: "reservation inconnue" });
    return;
  }
  const [removed] = bookings.splice(index, 1);
  res.json({ cancelled: removed.id });
});
import type { Result } from "./result.js";

export type Slot = { start: string; end: string };

const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * Creneaux libres d'une salle pour un jour UTC (YYYY-MM-DD), en ISO 8601 Z.
 */
export function freeSlots(
  date: string,
  bookings: ReadonlyArray<{ startsAt: string; endsAt: string }>
): Result<Slot[], string> {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    return { ok: false, error: "date invalide : format attendu AAAA-MM-JJ" };
  }
  const dayStart = Date.parse(`${date}T00:00:00Z`);
  if (Number.isNaN(dayStart) || new Date(dayStart).toISOString().slice(0, 10) !== date) {
    return { ok: false, error: "date invalide : jour inexistant au calendrier" };
  }
  const dayEnd = dayStart + DAY_MS;

  const busy = bookings
    .map((b) => ({
      start: Math.max(Date.parse(b.startsAt), dayStart),
      end: Math.min(Date.parse(b.endsAt), dayEnd),
    }))
    .filter((b) => b.start < b.end)
    .sort((a, b) => a.start - b.start);

  const slots: Slot[] = [];
  let cursor = dayStart;
  for (const b of busy) {
    if (b.start > cursor) {
      slots.push({ start: new Date(cursor).toISOString(), end: new Date(b.start).toISOString() });
    }
    cursor = Math.max(cursor, b.end);
  }
  if (cursor < dayEnd) {
    slots.push({ start: new Date(cursor).toISOString(), end: new Date(dayEnd).toISOString() });
  }
  return { ok: true, value: slots };
}

